(async () => {
  const t = await (await fetch(location.href)).text(), d = new DOMParser().parseFromString(t, 'text/html');
  const imgs = [...d.querySelectorAll('img.poster')];
  const rows = await Promise.all(imgs.map(i => new Promise(res => {
    const h = i.closest('[data-ref]') || i.closest('[data-key]'), id = h.dataset.ref || h.dataset.key, im = new Image();
    im.onload = () => res(id + ' ' + im.naturalWidth + 'x' + im.naturalHeight + ' ' + Math.round(i.src.length / 1024) + 'KB');
    im.onerror = () => res(id + ' BROKEN');
    im.src = i.src;
  })));
  return { inSource: imgs.length, stillInPage: document.querySelectorAll('img.poster').length, rows };
})()

(async () => {
  __focus(); __state('*', 'idle'); __anim(0);
  const t = await (await fetch(location.href)).text(), d = new DOMParser().parseFromString(t, 'text/html');
  let n = 0;
  for (const img of d.querySelectorAll('img.poster')) {
    const h = img.closest('[data-ref]') || img.closest('[data-key]');
    const view = document.querySelector((h.dataset.ref ? '[data-ref="' + h.dataset.ref + '"]' : '[data-key="' + h.dataset.key + '"]') + ' .view');
    if (!view) continue;
    view.querySelector('canvas').style.visibility = 'hidden';
    for (const l of view.querySelectorAll('.labels')) l.style.visibility = 'hidden';
    view.prepend(document.importNode(img, true)); n++;
  }
  await Promise.all([...document.querySelectorAll('img.poster')].map(i => i.decode().catch(() => null)));
  window.scrollTo(0, 0);
  return n;
})()
